import pandas as pd

def clean(df):
    df = df.copy()
    # strip whitespace from object columns
    for col in df.select_dtypes(include='object').columns:
        df[col] = df[col].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # fix known label variants
    if 'island' in df.columns:
        df['island'] = df['island'].replace({'Bisco': 'Biscoe'})
    # convert columns that are stored as text numbers
    num_cols = ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']
    for col in num_cols:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # enforce unique penguin_id
    if 'penguin_id' in df.columns:
        df = df.drop_duplicates(subset=['penguin_id'], keep='first')
    return df

def answer(df):
    df = df.copy()
    # ensure numeric for aggregation
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    # drop rows without species or mass
    df = df.dropna(subset=['species', 'body_mass_g'])
    totals = df.groupby('species')['body_mass_g'].sum()
    # return mapping species -> total mass
    return {str(k): float(v) for k, v in totals.items()}
